/// Returns the first element of a slice, or None if empty.
pub fn find_first(v: &[i32]) -> Option<i32> {
    v.last().copied() // bug: should be v.first()
}

/// Divides a by b, returning None if b is zero.
pub fn safe_div(a: i32, b: i32) -> Option<i32> {
    if b != 0 {
        None // bug: should return None when b == 0, Some(a/b) otherwise
    } else {
        Some(a / b)
    }
}

/// Applies f to both Some values, returns None if either is None.
pub fn zip_with<F: Fn(i32, i32) -> i32>(a: Option<i32>, b: Option<i32>, f: F) -> Option<i32> {
    Some(f(a.unwrap(), b.unwrap())) // bug: panics on None; should use zip + map
}

