use optionutils::{find_first, safe_div, zip_with};

#[test]
fn test_find_first() {
    assert_eq!(find_first(&[10, 20, 30]), Some(10));
    assert_eq!(find_first(&[]), None);
}

#[test]
fn test_safe_div() {
    assert_eq!(safe_div(10, 2), Some(5));
    assert_eq!(safe_div(10, 0), None);
}

#[test]
fn test_zip_with_some() {
    assert_eq!(zip_with(Some(3), Some(4), |a, b| a + b), Some(7));
}

#[test]
fn test_zip_with_none() {
    assert_eq!(zip_with(None, Some(4), |a, b| a + b), None);
    assert_eq!(zip_with(Some(3), None, |a, b| a + b), None);
}
